command:
id -u infraset-nodejs >/dev/null 2>&1 || sudo useradd --system --home /opt/infraset-nodejs --shell /usr/sbin/nologin infraset-nodejs
sudo install -d -o root -g root -m 0755 /opt/infraset-nodejs
sudo tee /opt/infraset-nodejs/server.js >/dev/null <<'ANTRIEB_NODEJS_EOF'
'use strict';
var http = require('http');
var body = 'infraset-nodejs';
var server = http.createServer(function (req, res) {
  if (req.url.split('?')[0] !== '/') {
    res.writeHead(404, {'Content-Type': 'text/plain', 'Content-Length': '9'});
    res.end('not found');
    return;
  }
  res.writeHead(200, {'Content-Type': 'text/plain', 'Content-Length': String(Buffer.byteLength(body))});
  res.end(body);
});
server.listen(3000, '127.0.0.1');
ANTRIEB_NODEJS_EOF
sudo chmod 0644 /opt/infraset-nodejs/server.js
sudo tee /etc/systemd/system/infraset-nodejs.service >/dev/null <<'ANTRIEB_SERVICE_EOF'
[Unit]
Description=InfraSet Node.js HTTP application
After=network.target

[Service]
Type=simple
User=infraset-nodejs
Group=infraset-nodejs
WorkingDirectory=/opt/infraset-nodejs
ExecStart=/usr/bin/nodejs /opt/infraset-nodejs/server.js
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
ANTRIEB_SERVICE_EOF
sudo systemctl daemon-reload
sudo systemctl enable infraset-nodejs.service
sudo systemctl restart infraset-nodejs.service
systemctl is-active infraset-nodejs.service
systemctl is-enabled infraset-nodejs.service

